<?php
declare(strict_types=1);
require_once __DIR__.'/db.php'; require_once __DIR__.'/functions.php'; requestMethod('POST');
try { ensureDatabase(); $d=getJsonBody(); $u=trim((string)($d['username']??'')); $e=trim((string)($d['email']??'')); $p=(string)($d['password']??''); if(!validateUsername($u)) jsonResponse(['status'=>'error','message'=>'Invalid username'],422); if(strlen($p)<6) jsonResponse(['status'=>'error','message'=>'Password must be at least 6 characters'],422); if($e!==''&&!filter_var($e,FILTER_VALIDATE_EMAIL)) jsonResponse(['status'=>'error','message'=>'Invalid email'],422); $s=db()->prepare('SELECT id FROM users WHERE username=? OR (?<>"" AND email=?) LIMIT 1'); $s->execute([$u,$e,$e]); if($s->fetch()) jsonResponse(['status'=>'error','message'=>'Username or email already exists'],409); $s=db()->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)'); $s->execute([$u,$e!==''?$e:null,password_hash($p,PASSWORD_DEFAULT)]); $id=(int)db()->lastInsertId(); jsonResponse(['status'=>'ok','message'=>'Registration successful','user'=>['id'=>$id,'username'=>$u,'email'=>$e!==''?$e:null],'token'=>issueToken($id)],201); } catch(Throwable $x) { jsonResponse(['status'=>'error','message'=>'Server error'],500); }
